    f.order_external_id                                            AS order_id,
    o.state                                                        AS order_state_code,
    CONVERT_TIMEZONE('UTC','Asia/Kolkata', o.created_at)::TIMESTAMP_NTZ     AS order_created_at_ist,
    CONVERT_TIMEZONE('UTC','Asia/Kolkata', c.cancelled_at_utc)::TIMESTAMP_NTZ AS cancelled_at_ist,
    DATEDIFF(minute, o.created_at, c.cancelled_at_utc)             AS mins_order_to_cancel,
    c.reason                                                       AS cancellation_reason,
    CASE c.cancellation_source WHEN 1 THEN 'Customer_App' WHEN 2 THEN 'Partner_App'
                               WHEN 3 THEN 'Salesforce'  WHEN 4 THEN 'Appsmith'
                               ELSE 'Unknown' END                  AS cancellation_source
FROM funnel_orders f
LEFT JOIN PROD_CURATED.PARTLOAD_APPLICATION.ORDERS o ON o.external_id = f.order_external_id
LEFT JOIN cancellations c ON c.order_id = o.id
ORDER BY f.order_external_id
